class Solution {
    public int maximumANDSum(int[] nums, int numSlots) {
        int[] powerOfThree = new int[numSlots + 1];
        powerOfThree[0] = 1;
        for (int i = 1; i <= numSlots; i++) {
            powerOfThree[i] = powerOfThree[i - 1] * 3;
        }

        // Each ternary digit records a slot's occupancy: 0, 1, or 2.
        int states = powerOfThree[numSlots];
        int[] dp = new int[states];
        java.util.Arrays.fill(dp, -1);
        dp[0] = 0;

        int answer = 0;
        for (int state = 0; state < states; state++) {
            if (dp[state] < 0) {
                continue;
            }

            int placed = 0;
            for (int remaining = state; remaining > 0; remaining /= 3) {
                placed += remaining % 3;
            }

            if (placed == nums.length) {
                answer = Math.max(answer, dp[state]);
                continue;
            }

            int remaining = state;
            for (int slot = 1; slot <= numSlots; slot++) {
                int occupancy = remaining % 3;
                remaining /= 3;

                if (occupancy < 2) {
                    int nextState = state + powerOfThree[slot - 1];
                    dp[nextState] = Math.max(
                        dp[nextState],
                        dp[state] + (nums[placed] & slot)
                    );
                }
            }
        }

        return answer;
    }
}

